SET SESSION group_concat_max_len = 10000000;

SELECT
GROUP_CONCAT(
    CONCAT(
        'SELECT ''',
        TABLE_NAME,
        ''' AS source_table, strand FROM `',
        TABLE_NAME,
        '` WHERE gene=''Os02428G0380001552.01'''
    )
    SEPARATOR ' UNION ALL '
)
INTO @sql
FROM (
    SELECT TABLE_NAME
    FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA='rgirs2DB'
    GROUP BY TABLE_NAME
    HAVING
        SUM(COLUMN_NAME='gene') > 0
        AND SUM(COLUMN_NAME='strand') > 0
) AS t;

PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

